00%);max-height:100%;overflow:auto;background:var(--pn);border:1.5px solid var(--ln);border-radius:16px;padding:18px;box-shadow:0 18px 60px #0009,inset 0 1px #ffffff0f;position:relative}.cd h2{margin:0 0 4px;font:700 22px Tektur;letter-spacing:.04em;text-transform:uppercase}.cd .sub{color:var(--mu);font-size:13px;margin:0 0 14px}.x{position:absolute;right:12px;top:12px;width:38px;height:38px;border-radius:10px;border:1.5px solid var(--ln);font-size:18px}.x:hover{background:#ffffff0f}.btn{display:flex;align-items:center;gap:12px;width:100%;padding:13px 16px;border-radius:12px;border:1.5px solid var(--ln);background:var(--pn2);text-align:left;margin-top:9px;transition:transform .08s,background .15s}.btn:hover{background:#2a1858}.btn:active{transform:scale(.98)}.btn b{font:700 16px Tektur;text-transform:uppercase;letter-spacing:.03em}.btn small{display:block;color:var(--mu);font-size:12px;font-weight:500}.btn .ic{font-size:22px;width:28px;text-align:center}.btn.pr{background:linear-gradient(180deg,#c99bff,#8a4dff);border-color:#e3cdff;color:#140726;box-shadow:0 6px 22px #a064ff59}.btn.pr small{color:#3a1b66}.btn.cy{background:linear-gradient(180deg,#7fe0ff,#2a9fd6);border-color:#c9f2ff;color:#04202d}.btn.cy small{color:#0a3e55}.two{display:grid;grid-template-columns:1fr 1fr;gap:9px}.two .btn{margin-top:9px}#s-main{background:radial-gradient(120% 90% at 30% 20%,#2c1460 0,#0d0720 60%)}.mm{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,360px);gap:28px;align-items:center;width:min(900px,100%)}.logo{text-align:center}.logo h1{margin:0;font:700 clamp(30px,6.4vw,58px)/.95 "Tektur";letter-spacing:.02em;background:linear-gradient(180deg,#fff,#c9a6ff 55%,#7f3dff);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 4px 18px rgba(150,90,255,.55));text-transform:uppercase}.logo .cj{display:inline-block;margin-top:8px;padding:4px 12px;border-radius:999px;background:var(--rd);color:#fff;font:700 13px Tektur;letter-spacing:.12em}.logo img{width:min(200px,42vw);image-rendering:pixelated;border-radius:10px;margin-top:16px;box-shadow:0 10px 40px #00000080}.logo p{color:var(--mu);font-size:13px;margin:10px 0 0}@media (max-width:700px){.mm{grid-template-columns:1fr;gap:10px}.logo img{display:none}.logo h1{font-size:34px}}@media (max-height:520px){.logo img{display:none}.mm{gap:12px}.btn{padding:9px 14px;margin-top:7px}}.tabs{display:flex;gap:6px;margin-bottom:10px}.tabs button{flex:1;padding:9px 6px;border-radius:10px;border:1.5px solid var(--ln);background:#0003;text-align:center}.tabs button b{display:block;font:700 13px Tektur;text-transform:uppercase}.tabs button small{color:var(--mu);font-size:11px}.tabs button.ac{background:linear-gradient(180deg,#c99bff,#8a4dff);color:#140726;border-color:#e3cdff}.tabs button.ac small{color:#3a1b66}#tl{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:7px}.tr{display:flex;align-items:center;gap:9px;padding:9px 10px;border-radius:10px;border:1.5px solid var(--ln);background:var(--pn2);text-align:left}.tr i{font-style:normal;width:26px;height:26px;display:grid;place-items:center;border-radius:7px;background:#ffffff14;font:700 12px Tektur}.tr span{flex:1;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.tr small{color:var(--gr);font-size:12px}.tr.dn i{background:var(--gr);color:#06200d}.tr.lk{opacity:.45;cursor:default}.tr:not(.lk):hover{background:#2a1858}.bk{display:block;width:100%;text-align:left;padding:12px 14px;border-radius:12px;border:1.5px solid var(--ln);background:var(--pn2);margin-top:8px}.bk b{font:700 18px Tektur}.bk small{display:block;color:var(--mu);font-size:12px}.bk.ac{border-color:var(--yl);box-shadow:0 0 0 2px #ffd23c40 inset}.bk.ac b:after{content:" ✓";color:var(--yl)}.sr{display:flex;justify-content:space-between;width:100%;padding:12px 14px;border-radius:12px;border:1.5px solid var(--ln);background:var(--pn2);margin-top:8px}.sr b{color:var(--yl)}.help p{margin:6px 0;color:#dcd2f5;font-size:14px;line-height:1.45}.help kbd{display:inline-block;min-width:26px;padding:2px 6px;border-radius:6px;background:#2d1a5c;border:1px solid var(--ln);text-align:center;font:600 12px Tektur}.res{text-align:center}.res .big{font:700 46px Tektur;color:var(--yl);margin:6px 0;text-shadow:0 4px 20px rgba(255,210,60,.4)}#rbest{color:var(--gr);font-weight:700}.pl{display:flex;align-items:center;gap:9px;padding:6px 8px;border-radius:9px;background:#00000040;margin-top:5px;font-size:13px;text-align:left}.pl i{font-style:normal;width:22px;height:22px;border-radius:6px;display:grid;place-items:center;color:#140726;font:700 12px Tektur}.pl span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.pl b{color:var(--mu);font-weight:600}#hud{display:none}body.ingame #hud{display:block}.hb{position:fixed;top:max(10px,env(safe-area-inset-top));width:44px;height:44px;border-radius:12px;background:#140a2db3;border:1.5px solid var(--ln);font-size:20px;z-index:5;display:grid;place-items:center}#hpause{left:max(10px,env(safe-area-inset-left))}#hsnd{left:calc(max(10px,env(safe-area-inset-left)) + 104px)}#hbike{left:calc(max(10px,env(safe-area-inset-left)) + 156px)}@media (max-width:520px){.hb{width:40px;height:40px;font-size:18px}#hrst{left:calc(max(10px,env(safe-area-inset-left)) + 46px)!important}#hsnd{left:calc(max(10px,env(safe-area-inset-left)) + 92px)!important}#hbike{left:calc(max(10px,env(safe-area-inset-left)) + 138px)!important}}#hzv{position:fixed;left:50%;top:40%;transform:translate(-50%,-50%);font:700 28px Tektur;padding:8px 16px;border-radius:12px;background:#140a2dbf;color:#fff;opacity:0;transition:opacity .25s;pointer-events:none;z-index:6}#hzv.on{opacity:1}#hrst{left:calc(max(10px,env(safe-area-inset-left)) + 52px)}#htimer{position:fixed;top:max(10px,env(safe-area-inset-top));right:max(12px,env(safe-area-inset-right));text-align:right;z-index:5;pointer-events:none}#htime{font:700 30px Tektur;letter-spacing:.02em;text-shadow:0 2px 0 #000,0 0 18px rgba(176,123,255,.6)}#hbest{display:block;font-size:12px;color:var(--mu)}#hbar{position:fixed;left:50%;transform:translate(-50%);top:max(18px,env(safe-area-inset-top));width:min(36vw,300px);height:8px;border-radius:5px;background:#00000073;border:1px solid var(--ln);overflow:hidden;z-index:5;pointer-events:none}#hprog{height:100%;width:0;background:linear-gradient(90deg,var(--ac),var(--gr))}#hmsg{position:fixed;left:0;right:0;top:24%;text-align:center;font:700 clamp(24px,5vw,44px) "Tektur";text-transform:uppercase;color:#fff;text-shadow:0 3px 0 #000,0 0 24px rgba(255,90,106,.8);pointer-events:none;opacity:0;z-index:5}#hcd{position:fixed;left:0;right:0;top:34%;text-align:center;font:700 120px Tektur;color:var(--yl);text-shadow:0 6px 0 #000;pointer-events:none;z-index:6}#hpl{position:fixed;left:max(10px,env(safe-area-inset-left));top:calc(max(10px,env(safe-area-inset-top)) + 54px);width:190px;z-index:5;pointer-events:none}#hpl .pl{background:#0a051999;padding:4px 7px}.pad{position:fixed;bottom:max(14px,env(safe-area-inset-bottom));width:clamp(64px,16vmin,96px);height:clamp(64px,16vmin,96px);border-radius:20px;background:#1e10428c;border:2px solid rgba(200,170,255,.35);display:grid;place-items:center;font-size:clamp(24px,6vmin,36px);z-index:5;touch-action:none;color:#fff}.pad small{position:absolute;bottom:4px;font:600 10px Tektur;color:var(--mu);text-transform:uppercase}.pad.on{background:#b07bff8c;border-color:#e3cdff;transform:scale(.95)}#pback{left:max(14px,env(safe-area-inset-left))}#pfwd{left:calc(max(14px,env(safe-area-inset-left)) + clamp(72px,18vmin,106px))}#pgas{right:max(14px,env(safe-area-inset-right));background:#288c468c;border-color:#82ffa073}#pbrk{right:calc(max(14px,env(safe-area-inset-right)) + clamp(72px,18vmin,106px));background:#8c1e3280;border-color:#ff829673}#pgas.on{background:#5dff7a99}#pbrk.on{background:#ff5a6aa6}@media (hover:hover) and (pointer:fine){.pad{opacity:.55}.pad:hover{opacity:1}}@media (max-width:600px){#hbar{top:calc(max(10px,env(safe-area-inset-top)) + 54px);width:calc(100vw - 32px)}#hpl{top:calc(max(10px,env(safe-area-inset-top)) + 70px)}}body.paper #htime{color:#1b1b1f;text-shadow:none}body.paper #hbest{color:#6b6478}body.paper .hb{background:#ffffffd9;border-color:#1b1b1f;color:#1b1b1f}body.paper #hbar{background:#1b1b1f14;border-color:#1b1b1f}body.paper #hprog{background:#e8412c}body.paper #hmsg{color:#1b1b1f;text-shadow:3px 3px 0 #e8412c}body.paper #hcd{color:#e8412c;text-shadow:4px 4px 0 #1b1b1f}body.paper .pad{background:#ffffffb3;border-color:#1b1b1f;color:#1b1b1f}body.paper .pad small{color:#1b1b1f}body.paper #pgas{background:#78dc8c8c;border-color:#1b1b1f}body.paper #pbrk{background:#ff8c968c;border-color:#1b1b1f}body.paper .pad.on{background:#e8412c;color:#fff}body.paper #hpl .pl{background:#ffffffd9;color:#1b1b1f}#toast{position:fixed;left:50%;bottom:120px;transform:translate(-50%,20px);background:#140a2deb;border:1.5px solid var(--ln);padding:9px 16px;border-radius:12px;opacity:0;transition:.25s;z-index:40;pointer-events:none;font-size:14px;max-width:calc(100vw - 32px);text-align:center}#toast.on{opacity:1;transform:translate(-50%)}#s-mp .cd{width:min(640px,100%)}.st{padding:9px 12px;border-radius:10px;background:#28c85a1f;border:1px solid rgba(93,255,122,.3);font-size:13px;margin:6px 0}.er{color:var(--rd);font-size:13px;min-height:0}.nl{display:flex;align-items:center;gap:8px;margin:12px 0 6px;font:700 13px Tektur;text-transform:uppercase;color:var(--mu)}.nl i{font-style:normal;width:20px;height:20px;border-radius:6px;background:var(--ac);color:#140726;display:grid;place-items:center;font-size:12px}.rw{display:flex;gap:8px;margin-top:8px}.rw button,.rw2 button{padding:10px 14px;border-radius:10px;border:1.5px solid var(--ln);background:var(--pn2);font-weight:700;white-space:nowrap}.rw button.pr,.rm button.pr{background:linear-gradient(180deg,#c99bff,#8a4dff);border-color:#e3cdff;color:#140726}.rw button.ac{background:linear-gradient(180deg,#7fe0ff,#2a9fd6);color:#04202d;border-color:#c9f2ff}.seg{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.seg button{padding:9px 6px;border-radius:10px;border:1.5px solid var(--ln);background:#0003;text-align:center}.seg b{display:block;font-size:13px}.seg small{color:var(--mu);font-size:11px}.seg button.ac{border-color:var(--yl);background:#ffd23c1f}.ng{display:grid;grid-template-columns:1fr 1fr;gap:8px}@media (max-width:560px){.ng{grid-template-columns:1fr}}.nc{padding:12px;border-radius:12px;border:1.5px solid var(--ln);background:#0003}.nc h4{margin:0 0 4px;font:700 14px Tektur}.nc p{margin:0;color:var(--mu);font-size:12.5px;line-height:1.4}.rm{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 8px;border-radius:9px;background:#ffffff0a;margin-top:6px;font-size:13px}.rm button{padding:7px 12px;border-radius:9px;border:1.5px solid var(--ln);font-weight:700}.rm small{display:block;color:var(--mu);font-size:11px}.rh{display:flex;justify-content:space-between;align-items:center;font:700 12px Tektur;color:var(--mu);text-transform:uppercase}.rh button{font-size:11px;color:var(--mu);text-decoration:underline}#mprec{padding:10px;border-radius:12px;border:1.5px solid rgba(255,210,60,.35);background:#ffd23c0f;margin-bottom:6px}.rm2{font-size:12px;color:var(--yl)}.em{color:var(--mu);font-size:12.5px;margin:6px 0 0}.cnt{color:var(--yl)}details{margin-top:8px;font-size:12.5px;color:var(--mu)}summary{cursor:pointer}.qv{display:flex;justify-content:center;margin:8px 0}#mpq{width:min(240px,70vw);height:auto;image-rendering:pixelated;border-radius:8px;background:#fff}textarea{height:64px;margin-top:8px;font:12px monospace;resize:none}.nf{display:flex;align-items:center;gap:10px;margin-top:12px}.nf button{padding:9px 14px;border-radius:10px;border:1.5px solid var(--ln);font-weight:700;white-space:nowrap}.nf small{color:var(--mu);font-size:11.5px}#mproom{margin-top:10px;padding:12px;border-radius:12px;border:1.5px solid rgba(93,255,122,.35);background:#5dff7a0f}#mprace{font-size:13px;color:var(--yl);margin:6px 0}#edbar{position:fixed;left:50%;transform:translate(-50%);bottom:calc(env(safe-area-inset-bottom) + 10px);z-index:30;display:none;gap:6px;flex-wrap:wrap;justify-content:center;max-width:calc(100vw - 16px)}#edbar button{font:700 14px system-ui,sans-serif;color:#1b1b1f;background:#fff;border:2px solid #1b1b1f;border-radius:12px;padding:9px 12px;box-shadow:0 3px #1b1b1f;cursor:pointer;touch-action:manipulation}#edbar button:active{transform:translateY(2px);box-shadow:0 1px #1b1b1f}#edbar button.go{background:#e8412c;color:#fff}body.drawing #hud{display:none!important}body.drawing #cv{touch-action:none;cursor:crosshair}#trkcode{position:fixed;inset:0;z-index:60;display:none;align-items:center;justify-content:center;background:#0a06148c}#trkcode .tc-in{background:#fbf9f2;color:#1b1b1f;border:2px solid #1b1b1f;border-radius:14px;padding:14px;width:min(420px,92vw);display:flex;flex-direction:column;gap:8px;font:14px system-ui,sans-serif}#trkcode textarea{height:90px;font:11px monospace;word-break:break-all}#trkcode .rw{display:flex;gap:8px}#trkcode button{flex:1;font:700 14px system-ui,sans-serif;padding:9px;border-radius:10px;border:2px solid #1b1b1f;background:#fff;cursor:pointer}#tl em{font-style:normal;margin-right:6px;padding:2px 4px;border-radius:6px;cursor:pointer}#tl em:hover{background:#00000014}</style>
</head>
<body>
<canvas id="cv"></canvas>
<div id="hud">
  <button class="hb" id="hpause" aria-label="Пауза">⏸</button>
  <button class="hb" id="hrst" aria-label="Заново">↻</button>
  <button class="hb" id="hsnd" aria-label="Звук">🔊</button><button class="hb" id="hbike" aria-label="Мотоцикл">🏍</button><div id="hzv"></div>
  <div id="hbar"><div id="hprog"></div></div>
  <div id="htimer"><div id="htime">0:00.00</div><span id="hbest"></span></div>
  <div id="hmsg"></div><div id="hcd" style="display:none"></div>
  <div id="hpl"></div>
  <div class="pad" id="pback">⟲<small>назад</small></div>
  <div class="pad" id="pfwd">⟳<small>вперёд</small></div>
  <div class="pad" id="pbrk">■<small>тормоз</small></div>
  <div class="pad" id="pgas">▲<small>газ</small></div>
</div>
<div id="toast"></div>

<div class="scr open" id="s-main"><div class="mm">
  <div class="logo"><h1>Gravity<br>Defied</h1><span class="cj">CRAZY JUMP</span><br><img id="splash" alt=""><p id="mprog"></p></div>
  <div>
    <button class="btn pr" id="bplay"><span class="ic">▶</span><span><b>Играть</b><small>Следующая непройденная трасса</small></span></button>
    <button class="btn" id="bdraw"><span class="ic">✏️</span><span><b>Рисовать трассу</b><small>Нарисуй пальцем и поделись с другом</small></span></button>
    <button class="btn" id="btracks"><span class="ic">🗺</span><span><b>Трассы</b><small>3 лиги · 52 трассы из оригинала</small></span></button>
    <button class="btn" id="bbike"><span class="ic">🏍</span><span><b>Мотоцикл</b><small id="mbike"></small></span></button>
    <button class="btn" id="bstyle"><span class="ic">🧢</span><span><b>Стиль гонщика</b><small>шапки, шлемы, кофты</small></span></button>
    <button class="btn cy" id="bmp"><span class="ic">📡</span><span><b>Мультиплеер</b><small>Онлайн · Wi‑Fi · QR — до 4 гонщиков</small></span></button>
    <button class="btn" id="blang"><span class="ic">Aa</span><span><b data-lt>Язык: Русский → English</b></span></button>
    <div class="two"><button class="btn" id="bsave"><span class="ic">💾</span><span><b>Сохранить</b><small>в файл .txt</small></span></button><button class="btn" id="bload"><span class="ic">📂</span><span><b>Загрузить</b><small>из файла</small></span></button></div>
    <div class="two"><button class="btn" id="bset"><span class="ic">⚙</span><span><b>Настройки</b></span></button><button class="btn" id="bhelp"><span class="ic">?</span><span><b>Помощь</b></span></button></div>
    <button class="btn" id="bsnd" data-snd><span class="ic">🔊</span><span><b>Звук: вкл</b><small>нажми, чтобы выключить</small></span></button>
  </div>
</div></div>

<div class="scr" id="s-pause"><div class="cd">
  <h2>Пауза</h2><p class="sub" id="pname"></p>
  <button class="btn pr" id="bres"><span class="ic">▶</span><span><b>Продолжить</b></span></button>
  <button class="btn" id="brst"><span class="ic">↻</span><span><b>Заново</b><small>Клавиша R</small></span></button>
  <div class="two"><button class="btn" id="btr2"><span class="ic">🗺</span><span><b>Трассы</b></span></button><button class="btn" id="bbk2"><span class="ic">🏍</span><span><b>Мотоцикл</b></span></button></div>
  <button class="btn cy" id="bmp2"><span class="ic">📡</span><span><b>Мультиплеер</b></span></button>
  <button class="btn" id="bsnd2" data-snd><span class="ic">🔊</span><span><b>Звук: вкл</b><small>нажми, чтобы выключить</small></span></button>
  <button class="btn" id="bexit"><span class="ic">⌂</span><span><b>Главное меню</b></span></button>
</div></div>

<div class="scr" id="s-tracks"><div class="cd" style="width:min(760px,100%)">
  <button class="x" data-back aria-label="Закрыть">✕</button>
  <h2>Трассы</h2><p class="sub">Пройди трассу — откроется следующая. Время считается от стартового флага.</p>
  <div class="tabs" id="tl-tabs"></div><div id="tl"></div>
</div></div>

<div class="scr" id="s-bikes"><div class="cd">
  <button class="x" data-back aria-label="Закрыть">✕</button>
  <h2>Мотоцикл</h2><p class="sub">20 мотоциклов: у каждого своя физика мотора и наклона. Дорогие — быстрее и с помощником равновесия. Монеты дают за финиш.</p>
  <div id="bl"></div>
</div></div>

<div class="scr" id="s-style"><div class="cd" style="width:min(760px,100%)">
  <button class="x" data-back aria-label="Закрыть">✕</button>
  <h2>Стиль гонщика</h2><p class="sub">Выбери, что надеть. Видно и тебе, и друзьям в сетевой игре.</p>
  <canvas id="stpv" width="240" height="150" style="display:block;margin:0 auto 8px;max-width:100%"></canvas>
  <h3 style="margin:6px 0">На голову</h3><div id="sthat" class="wgrid"></div>
  <h3 style="margin:10px 0 6px">Одежда</h3><div id="sttop" class="wgrid"></div>
</div></div>
<style>.wgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(64px,1fr));gap:6px}.wgrid button{height:64px;border-radius:12px;border:2px solid rgba(255,255,255,.14);background:rgba(255,255,255,.06);display:flex;align-items:center;justify-content:center;cursor:pointer;padding:4px;color:inherit;font:600 11px inherit}.wgrid button.ac{border-color:#ffd23c;background:rgba(255,210,60,.16)}.wgrid img{max-width:100%;max-height:100%}</style>

<div class="scr" id="s-set"><div class="cd">
  <button class="x" data-back aria-label="Закрыть">✕</button>
  <h2>Настройки</h2><div id="setl"></div>
</div></div>

<div class="scr" id="s-help"><div class="cd help">
  <button class="x" data-back aria-label="Закрыть">✕</button>
  <h2>Как играть</h2>
  <p><b>Газ</b> — <kbd>↑</kbd> или <kbd>W</kbd>. <b>Тормоз</b> — <kbd>↓</kbd> или <kbd>S</kbd>.</p>
  <p><b>Наклон назад</b> — <kbd>←</kbd>/<kbd>A</kbd>, <b>вперёд</b> — <kbd>→</kbd>/<kbd>D</kbd>. Наклоном выравнивай мотоцикл в прыжке и приземляйся на оба колеса.</p>
  <p><kbd>R</kbd> — заново, <kbd>Esc</kbd> — пауза. На телефоне слева кнопки наклона, справа — газ и тормоз (можно жать несколько сразу).</p>
  <p>Разбился, если гонщик ударился головой или мотоцикл сломался. Финиш — у клетчатого флага.</p>
  <p>Физика и трассы перенесены из оригинальной игры один в один.</p>
</div></div>

<div class="scr" id="s-res"><div class="cd res">
  <h2 id="rtitle">Финиш!</h2><p class="sub" id="rname"></p>
  <div class="big" id="rtime"></div><div id="rbest"></div>
  <div id="rboard"></div>
  <button class="btn pr" id="rnext"><span class="ic">▶</span><span><b>Следующая трасса</b></span></button>
  <div class="two"><button class="btn" id="ragain"><span class="ic">↻</span><span><b>Ещё раз</b></span></button><button class="btn" id="rmenu"><span class="ic">🗺</span><span><b>Трассы</b></span></button></div>
</div></div>

<div class="scr" id="s-mp"><div class="cd">
  <button class="x" data-back aria-label="Закрыть">✕</button>
  <h2>Мультиплеер</h2><p class="sub">До 4 гонщиков на одной трассе. Каждый едет на своём мотоцикле и видит соперников.</p>
  <div class="st" id="mps"></div><div class="er" id="mper"></div>
  <div id="mproom" style="display:none"><div id="mpplayers"></div><div id="mprace"></div><div class="rw"><button class="pr" id="mppick">🏁 Выбрать трассу и начать гонку</button></div></div>
  <div id="mpsetup">
    <div id="mprec" style="display:none"></div>
    <label class="nl" for="mpn"><i>1</i>Твоё имя</label><div class="rw"><input id="mpn" maxlength="16" placeholder="Твоё имя" autocomplete="off"></div>
    <div class="nl"><i>2</i>Как подключаться</div>
    <div class="seg"><button id="mt5"><b>🌍 Онлайн</b><small>по интернету, в 1 нажатие</small></button><button id="mt1"><b>📡 Wi‑Fi</b><small>в одной сети</small></button><button id="mt4"><b>📷 QR и коды</b><small>без интернета</small></button></div>
    <div class="nl"><i>3</i>Создай игру или зайди в чужую</div>
    <div id="mpp5" style="display:none"><div class="ng"><div class="nc"><h4>⚡ Быстрая игра</h4><p>Нажми — игра сама найдёт открытую комнату или создаст свою. С друзьями: все вводят <b>одно и то же слово</b> и жмут кнопку (слово = пароль).</p><div class="rw"><input id="mpw" maxlength="32" placeholder="слово-пароль (можно пусто)" autocomplete="off" autocapitalize="off"></div><div class="rw"><button class="pr" id="mpqk">⚡ Играть онлайн</button><button id="mpqc" style="display:none">Отмена</button></div></div>
      <div class="nc"><h4>🔎 Открытые комнаты <span class="cnt" id="mponc"></span></h4><div id="mporl"></div></div></div>
      <details><summary>Не соединяется?</summary><p>Игра идёт напрямую между устройствами, поэтому в мобильном интернете соединение может не пройти — попробуйте Wi‑Fi. Новые комнаты видны через несколько секунд.</p></details></div>
    <div id="mpp1" style="display:none"><div class="ng"><div class="nc"><h4>🎮 Создать игру</h4><p>Ты станешь хостом. Друзья из твоей Wi‑Fi сети увидят игру в своём списке.</p><div class="rw"><button class="pr" id="mpah">Создать игру</button><button id="mpau" style="display:none">Отменить игру</button></div></div>
      <div class="nc"><h4>🔎 Доступные игры <span class="cnt" id="mpnac"></span></h4><div id="mparl"></div></div></div>
      <details><summary>Список пуст, хотя друг уже создал игру?</summary><p>Если список пуст — введите <b>одно и то же слово</b> на обоих устройствах и нажмите «Применить».</p><div class="rw"><input id="mpwr" placeholder="слово комнаты"><button id="mpwgo">Применить</button></div></details></div>
  </div>
  <div id="mpp4"><div id="mp0" class="ng">
    <div class="nc"><h4>🎮 Создать игру</h4><p>Ты — хост. Друзей подключаешь по QR‑коду.</p><div class="rw"><button class="pr" id="mph">Создать игру</button></div></div>
    <div class="nc"><h4>🙋 Присоединиться</h4><p>Сфотографируй QR хоста или вставь его код.</p><div class="rw"><button class="ac" id="mpj">Присоединиться</button></div></div>
  </div></div>
  <div id="mp1"><div class="nc"><h4>🎮 Ты — хост</h4><p>Подключай друзей по одному: каждому нужен свой QR‑код.</p><div class="rw"><button class="pr" id="mpa">➕ Добавить игрока</button></div></div></div>
  <div id="mpx"><div class="nc">
    <p id="mpt"></p>
    <div class="qv"><canvas id="mpq"></canvas></div>
    <input id="mpf" type="file" accept="image/*" capture="environment" hidden>
    <textarea id="mpo" readonly></textarea>
    <div class="rw"><button id="mpcp">📋 Копировать</button></div>
    <textarea id="mpm" placeholder="код друга"></textarea>
    <div class="rw"><button class="ac" id="mpsc">📷 Сфотографировать</button><button class="pr" id="mpok">OK</button></div>
  </div></div>
  <div class="nf"><button id="mpl">Выйти</button><small>Игра идёт напрямую между устройствами. Удачные подключения запоминаются — повтор в одно нажатие.</small></div>
</div></div>

